/** Sprite atlas manifest (assets/atlas/atlas.json, generated by scripts/gen-atlas.ts). */

export interface AtlasFrame {
  x: number;
  y: number;
  w: number;
  h: number;
  /** Trim offset inside the 316×436 source canvas. */
  ox: number;
  oy: number;
}

export interface CharacterAtlas {
  image: string;
  size: { w: number; h: number };
  canvas: { w: number; h: number };
  /** Canvas y of the feet (bottom of the idle pose). */
  baseline: number;
  contentHeight: number;
  frames: Readonly<Record<string, AtlasFrame>>;
}

export interface AtlasManifest {
  schemaVersion: 1;
  characters: Readonly<Record<string, CharacterAtlas>>;
}

export function parseAtlasManifest(input: unknown): AtlasManifest {
  const o = input as AtlasManifest;
  if (!o || o.schemaVersion !== 1 || typeof o.characters !== 'object') throw new Error('atlas.json: unsupported manifest');
  for (const [id, c] of Object.entries(o.characters)) {
    if (!c.frames?.idle) throw new Error(`atlas.json: ${id} has no idle frame`);
    for (const [pose, f] of Object.entries(c.frames)) {
      if (f.x + f.w > c.size.w || f.y + f.h > c.size.h) throw new Error(`atlas.json: ${id}/${pose} is outside the atlas`);
    }
  }
  return o;
}

/** World units per sprite pixel: the courtroom was built for a 63-unit character (SCENE-GUIDE). */
export function worldPerPixel(atlas: AtlasManifest): number {
  const heights = Object.values(atlas.characters)
    .map((c) => c.contentHeight)
    .sort((a, b) => a - b);
  const median = heights[Math.floor(heights.length / 2)] ?? 270;
  return 63 / median;
}

/** UV rectangle (0..1, origin bottom-left as three.js expects). */
export function frameUv(atlas: CharacterAtlas, frame: AtlasFrame): { u0: number; v0: number; u1: number; v1: number } {
  return {
    u0: frame.x / atlas.size.w,
    u1: (frame.x + frame.w) / atlas.size.w,
    v0: 1 - (frame.y + frame.h) / atlas.size.h,
    v1: 1 - frame.y / atlas.size.h,
  };
}
